document.getElementById('app-data').append("\"},{\"caption\":\"\",\"src\":\"data:image/webp;base64,\"}],\"link\":\"https://docs.google.com/document/d/1rpQbqFp6bCQ588t6sq8ZObJoTxbrMeq7/edit\"},{\"title\":\"NPC 테이블 · 맵 상호작용 대상 정리\",\"description\":\"\",\"pages\":[{\"caption\":\"\",\"src\":\"data:image/webp;base64,\"}],\"link\":\"https://docs.google.com/spreadsheets/d/1Vv4__sIacBE5kPULIi-xJgyclH12YMLQ/edit\"}],\"resultsTabVersion\":1,\"portfolioIntro\":{\"kicker\":\"CHARACTER · STORY · EVENT/QUEST\",\"title\":\"캐릭터 설정과 4개 학년의 시나리오, 선택형 이벤트를 공동 기획한 포트폴리오\",\"summary\":\"\",\"points\":[\"캐릭터 공동 기획\",\"1~4학년 시나리오\",\"학년 이벤트\",\"탐색 이벤트·퀘스트\",\"NPC 상호작용 테이블\"]},\"universityPortfolio\":{\"setting\":{\"title\":\"게임 설정 · 대학 생활을 생존게임으로 재해석\",\"text\":\"겉으로는 엘리트 학교처럼 보이지만, 학생에게는 과제·시험·조별과제·졸업 논문이 끊임없이 이어지는 4년제 대학을 배경으로 구성했습니다. 학교 내부와 대학가를 오가며 학년 이벤트와 탐색 이벤트를 진행하는 구조입니다.\"},\"characters\":[{\"name\":\"김대학\",\"role\":\"주인공\",\"text\":\"게으르고 낙천적인 대학생. 학년이 오를 때마다 새로운 전투 스킬을 익히며 졸업을 목표로 진행.\",\"image\":\"data:image/webp;base64,\",\"intent\":\"\"},{\"name\":\"이지아\",\"role\":\"1학년 동료\",\"text\":\"겉으로는 활기차고 발랄하지만 실제로는 시니컬하고 털털한 성격을 감춘 캐릭터. 아군 디버프 제거 역할.\",\"image\":\"data:image/webp;base64,\",\"intent\":\"\"},{\"name\":\"김철수\",\"role\":\"2학년 동료\",\"text\":\"소극적이고 강함을 동경하는 학생. 운동 동아리 입부로 이어지는 성장 흐름과 탱커 역할을 연결.\",\"image\":\"data:image/webp;base64,\",\"intent\":\"\"},{\"name\":\"김비실\",\"role\":\"1·3학년 주요 인물\",\"text\":\"얍삽하고 속이 좁은 인물로 시작해 3학년에서 다시 만나 관계가 변화하는 캐릭터. 디버프 중심 능력.\",\"image\":\"data:image/webp;base64,\",\"intent\":\"\"},{\"name\":\"이하나\",\"role\":\"화석 선배 · 대학원생\",\"text\":\"OT 튜토리얼을 돕는 선배에서 대학원생으로 재등장하는 흑막 캐릭터. 초반과 후반의 인상을 대비시킨 설정.\",\"image\":\"data:image/webp;base64,\",\"intent\":\"\"}],\"events\":[{\"name\":\"대학 축제\",\"type\":\"1학년 이벤트\",\"text\":\"축제 참여 여부를 선택하고, 공연·가판대 등 선택에 따라 능력치 또는 재화 보상을 얻는 이벤트.\"},{\"name\":\"체육대회\",\"type\":\"2학년 이벤트\",\"text\":\"참여 여부와 참여 방식에 따라 체력·지력 보상이 달라지는 선택형 이벤트.\"},{\"name\":\"취업 박람회\",\"type\":\"3학년 이벤트\",\"text\":\"아르바이트로 재화를 얻거나 박람회를 관람해 지력을 얻는 진로 연계 이벤트.\"},{\"name\":\"고양이 밥주기\",\"type\":\"탐색 이벤트\",\"text\":\"편의점에서 캔사료를 구매한 뒤 고양이에게 사용하는 선행 조건형 이벤트.\"},{\"name\":\"물건 찾아주기\",\"type\":\"탐색 이벤트\",\"text\":\"필드에서 지갑을 먼저 획득해야 진행되는 상호작용 연계 이벤트.\"},{\"name\":\"동아리 홍보\",\"type\":\"탐색 이벤트\",\"text\":\"2학년 스토리 진행을 조건으로 열리며, 운동 동아리와 연결되는 아이템 보상 이벤트.\"}],\"references\":[\"캐릭터 기획서\",\"캐릭터 테이블\",\"NPC 테이블\",\"아이템 시스템 기획서\",\"전투 시스템 기획서 · 몬스터 및 스테이지\"],\"eventDetails\":[{\"title\":\"2학년 · 체육대회\",\"purpose\":\"\",\"tables\":[{\"title\":\"학년 이벤트 원문\",\"rows\":[[\"학년 이벤트 - 2학년\",\"학년 이벤트 - 2학년\"],[\"이벤트 이름\",\"체육대회\"],[\"설명\",\"마침내 다가온 2학년 체육 대회.\\n무엇을 할까?\"],[\"선택지1\",\"참여하지 않고 집에 숨어 있는다.\"],[\"선택지2\",\"체육대회에 참여한다.\"]]},{\"title\":\"참여 선택\",\"rows\":[[\"이벤트 참여 선택\",\"이벤트 참여 선택\"],[\"선택지1 선택\",\"선택지2 선택\"],[\"운동은 싫은데… 집에 숨어있어야 겠다.\\n체육대회를 참여하지 않았다. (육성 파트 진행)\",\"운동은 싫지만 학교행사니 참여할수 밖에\\n체육대회에 참여한다.\"]]},{\"title\":\"결과·보상\",\"rows\":[[\"이벤트 보상\",\"이벤트 보상\"],[\"선택지1 선택\",\"선택지2 선택\"],[\"체육대회에 선수로 참여(체력 상승)\\n…이번에는 선수로 참여해야겠어.\\n체육대회에서 선수로 참여해 우승했다. (체력 상승)\",\"운영위원으로 참여(지력 상승)\\n직접 참여하기보다 운영 위원으로 참여하는 게 편하지 않을까?\\n체육대회의 운영 위원으로 참여하며 많은 걸 배웠다. (지력 상승)\"]]}]},{\"title\":\"3학년 · 취업 박람회\",\"purpose\":\"\",\"tables\":[{\"title\":\"학년 이벤트 원문\",\"rows\":[[\"학년 이벤트 - 3학년\",\"학년 이벤트 - 3학년\"],[\"이벤트 이름\",\"취업 박람회\"],[\"설명\",\"취업 박람회가 열린다.\\n박람회에 참여해야 하는데… 어떻게 할까?\"],[\"선택지1\",\"박람회를 참여하지 않는다.\"],[\"선택지2\",\"취업 박람회에 참여한다.\"]]},{\"title\":\"참여 선택\",\"rows\":[[\"이벤트 참여 선택\",\"이벤트 참여 선택\"],[\"선택지1 선택\",\"선택지2 선택\"],[\"학교 수업만으로도 힘들다.\\n취업 박람회를 참여하지 않았다. (육성 파트 진행)\",\"흔치않은 기회이니 참여해 볼까?\\n취업 박람회에 참여한다.\"]]},{\"title\":\"결과·보상\",\"rows\":[[\"이벤트 보상\",\"이벤트 보상\"],[\"선택지1 선택\",\"선택지2 선택\"],[\"취업 박람회 아르바이트 참여(재화 획득)\\n…돈을 벌어야 해. 이번 박람회에서 아르바이트를 구한다고 하는데 한번 참여해볼까?\\n취업 박람회에서 아르바이트를 뛰어 일당을 받았다. (재화 획득)\",\"취업 박람회 관람(지력 상승)\\n자주 찾아오지 않는 기회다. 이번 박람회에 참여하면 뭐라도 얻지 않을까?\\n취업 박람회를 둘러보며 취업에 관한 정보를 얻었다. (지력 상승)\"]]}]}],\"processStatement\":[{\"title\":\"설정과 장기 시나리오\",\"work\":\"팀원과 함께 4년제 대학의 과제·시험·조별과제·대학원 진학을 학년별 사건과 갈등으로 구성하고, OT와 졸업을 시작·끝 지점으로 연결했습니다.\",\"result\":\"\"},{\"title\":\"캐릭터 수정·관계 설계\",\"work\":\"5월 31일 스토리 회의에서 평면적인 1학년 동료의 성격을 재검토하고, 이지아의 겉모습과 실제 성격을 구분했습니다. 김비실의 적→동료 변화, 김철수의 학년 간 성장, 화석 선배의 OT 조력자→후반 갈등 구도를 스토리 안에 연결했습니다.\",\"result\":\"\"},{\"title\":\"이벤트·퀘스트 작성\",\"work\":\"학년 이벤트는 참여 여부와 활동을 선택하게 하고, 그 결과를 능력치·재화·아이템 보상으로 구분했습니다. 탐색 이벤트는 지갑 획득, 캔사료 사용 등 선행 조건을 포함했습니다.\",\"result\":\"\"},{\"title\":\"실제 도입부 대사\",\"work\":\"교수들의 소개와 즉석 퀴즈, 튜토리얼 전투, 화석 선배 합류를 장면 지시와 대사로 작성했습니다.\",\"result\":\"\"}]},\"workJourney\":{\"kicker\":\"STORY CONCEPT · CHARACTER · EVENT\",\"title\":\"학년별 사건과 캐릭터 관계를 연결하는 스토리·이벤트 공동 기획\",\"summary\":\"\",\"steps\":[{\"label\":\"01 · CONCEPT\",\"title\":\"대학 생활을 “졸업까지 버티는 생존게임”으로 재구성\",\"intent\":\"\",\"work\":\"4년제 대학과 대학가 배경, 학년별 핵심 테마, 졸업을 최종 목표로 하는 전체 흐름을 공동 작성했습니다.\",\"skill\":\"\"},{\"label\":\"02 · CHARACTER REVISION\",\"title\":\"회의와 검토를 통해 캐릭터의 역할을 입체화\",\"challenge\":\"\",\"resolution\":\"\",\"result\":\"\",\"skill\":\"\"},{\"label\":\"03 · EVENT / QUEST\",\"title\":\"선택·조건·보상까지 포함한 이벤트 시나리오 작성\",\"work\":\"대학 축제·체육대회·취업 박람회 같은 학년 이벤트와 고양이 밥주기·분실물·동아리 홍보 같은 탐색 이벤트를 작성했습니다.\",\"result\":\"\",\"skill\":\"\"},{\"label\":\"04 · IN-GAME INTRO\",\"title\":\"OT 도입부를 실제 게임 대사와 전투 전환 흐름으로 작성\",\"work\":\"교수 소개 → 즉석 퀴즈 → 튜토리얼 전투 → 화석 선배 합류로 이어지는 도입부 대사를 작성했습니다.\",\"skill\":\"\"}]}},{\"id\":\"the_glitch\",\"title\":\"The Glitch\",\"english\":\"THE GLITCH\",\"kind\":\"personal\",\"year\":\"2026\",\"period\":\"2026.04.20 — 2026.04.27\",\"studio\":\"디벨로켓 · 기획 38기 3팀\",\"role\":\"팀장 · 시나리오 · QA · 텍스트/CG 배치\",\"genre\":\"퍼즐 비주얼노벨 · 방탈출 추리\",\"short\":\"\",\"description\":\"\",\"public\":true,\"featured\":false,\"featuredRank\":0,\"theme\":\"jade\",\"coverImageData\":\"data:image/webp;base64,");